1	import { CONFIG } from '../config';
2	import { device } from './device';
3	import { sun, setShadowQuality, stepShadows } from './lights';
4	import { reflectState } from './water';
5	import { clouds } from './sky';
6	import { bloomState, setPixelRatio, onResize } from './postprocessing';
7	import { rainShowing } from '../environment/weather/rain';
8	
9	/* =====================================================================
10	   CHẤT LƯỢNG HÌNH (D-018) — thang bậc ở CONFIG.perf.steps (0 = cảnh gốc). Chế độ:
11	   - 'auto': đo thời gian khung trung bình; chậm (> downMs) thì hạ một bậc, nhanh (< upMs) đủ lâu thì nâng một bậc.
12	   - 'high' | 'medium' | 'low': đứng yên ở bậc tương ứng (CONFIG.perf.manual).
13	   Khi chạy chỉ đổi những thứ không làm biên dịch lại shader: pixelRatio, cỡ shadow map, chu kỳ vẽ bóng / phản chiếu, độ phân giải bloom, số tấm mây.
14	   ?test: luôn bậc 0 và không tự đổi (bảng draw call chuẩn), trừ khi test gọi set().
15	   ===================================================================== */
16	export type QualityMode = 'auto' | 'high' | 'medium' | 'low';
17	type Step = (typeof CONFIG.perf.steps)[number];
18	const P = CONFIG.perf, STORE = 'dn3d-quality';
19	
20	const loadMode = (): QualityMode => {
21	  if (device.test) return 'high';
22	  try { const v = localStorage.getItem(STORE); if (v === 'auto' || v === 'high' || v === 'medium' || v === 'low') return v; } catch { /* trình duyệt chặn lưu trữ */ }
23	  return 'auto';
24	};
25	const startStep = (mode: QualityMode) => mode === 'auto' ? (device.phone ? P.start.phone : device.weak ? P.start.weak : 0) : P.manual[mode];
26	
27	let busy: () => boolean = () => false;
28	let winSum = 0, winN = 0, winT = 0, fastT = 0, lastChange = 0, last = 0;
29	let appliedStep: Step | null = null, appliedRatio = 0;
30	
31	export const quality = {
32	  mode: loadMode(),
33	  step: 0,
34	  changes: 0,                // số lần đã đổi bậc (test)
35	  adapt: { ...P.adapt },     // bản sao chỉnh được (test rút ngắn cửa sổ / thời gian giữ)
36	  simulateMs: 0,             // > 0: thay thời gian khung đo được bằng số này (test giả lập máy chậm / nhanh; bật cả khi ?test)
37	  /* Gọi một lần lúc khởi động, TRƯỚC prewarm: điện thoại ở bậc Thấp thì tắt castShadow từ đầu (đỡ lấy mẫu bóng; xem lights.ts) */
38	  init(isBusy?: () => boolean) {
39	    if (isBusy) busy = isBusy;
40	    this.step = startStep(this.mode);
41	    if (device.phone && P.steps[this.step].shadow === 0) sun.castShadow = false;
42	    this.apply(true);
43	  },
44	  /* Đổi chế độ (ô chọn / test). Lưu lựa chọn (trừ ?test) */
45	  set(mode: QualityMode) {
46	    this.mode = mode;
47	    if (!device.test) try { localStorage.setItem(STORE, mode); } catch { /* bỏ qua */ }
48	    this.step = startStep(mode); fastT = 0; winSum = winN = 0; winT = 0;
49	    this.apply(true);
50	  },
51	  current(): Step { return P.steps[this.step]; },
52	  /* Áp bậc hiện tại (pixelRatio có tính giới hạn khi mưa) */
53	  apply(force = false) {
